def post(a, r):
    # A run starts at s if s == 0 or a[s-1] >= a[s] (the previous step is not an increase).
    def is_start(s):
        if s == 0:
            return BoolVal(True)
        return a[s - 1] >= a[s]

    # Length of the maximal strictly increasing run starting at the concrete index s.
    # Extension to index k holds iff all steps from s up to k are strict increases,
    # and these conditions are prefix-closed, so the length is 1 + (number of valid k).
    def run_len(s):
        expr = 1
        for k in range(s + 1, N):
            ok = And([a[j] < a[j + 1] for j in range(s, k)])
            expr = expr + If(ok, 1, 0)
        return expr

    # r must be a run start.
    starts_r = Or([And(r == s, is_start(s)) for s in range(N)])

    # Length of the run starting at r.
    Lr = run_len(N - 1)
    for s in reversed(range(N - 1)):
        Lr = If(r == s, run_len(s), Lr)

    constraints = [r >= 0, r < N, starts_r]
    for s in range(N):
        # No run is longer than the one starting at r.
        constraints.append(Implies(is_start(s), run_len(s) <= Lr))
        # Ties go to the last run: any later run start must be strictly shorter.
        if s > 0:
            constraints.append(
                Implies(And(is_start(s), r < s), run_len(s) < Lr)
            )
    return And(constraints)
